(window.TNQ=window.TNQ||[]).push({"terms":{"청약":{"d":"계약을 맺으려는 상대방을 특정해 확정적으로 하는 의사표시","r":["승낙"]},"승낙":{"d":"청약에 동의한다는 의사표시로 도달한 때 효력이 생김","r":["청약"]},"청약의 유인":{"d":"불특정 다수에게 한 제안처럼 청약을 하도록 유도하는 행위","r":["청약"]},"도달주의":{"d":"의사표시가 상대방에게 도달한 때 효력이 생긴다는 원칙","r":[]},"개설은행":{"d":"신용장을 발행해 수익자에게 대금 지급을 약속하는 은행이다.","r":[]},"확인은행":{"d":"개설은행 외에 신용장 대금 지급을 추가로 확약하는 은행","r":["개설은행"]},"수익자":{"d":"신용장을 받아 대금을 청구할 수 있는 수출자","r":["개설의뢰인"]},"개설의뢰인":{"d":"은행에 신용장 개설을 요청한 수입자","r":["수익자"]},"환어음":{"d":"발행인이 지급인에게 일정 금액 지급을 위탁하는 어음","r":[]},"일람지급":{"d":"서류가 제시되면 즉시 대금을 지급하는 신용장 이용 방식","r":["연지급"]},"연지급":{"d":"서류 제시 후 정해진 날에 대금을 지급하는 이용 방식","r":["일람지급"]},"상환청구권":{"d":"어음을 매입한 자가 지급되지 않으면 되돌려 청구할 수 있는 권리","r":[]},"추심의뢰은행":{"d":"수출자로부터 추심을 의뢰받은 은행","r":["추심은행"]},"추심은행":{"d":"추심의뢰은행 이외에 추심에 관여하는 은행","r":["추심의뢰은행"]},"제시은행":{"d":"지급인에게 서류를 직접 제시하는 추심은행","r":["추심은행"]},"화환추심":{"d":"상업서류를 금융서류와 함께 또는 단독으로 추심하는 방식","r":[]},"체선료":{"d":"허용된 정박기간을 넘긴 데 대해 선주에게 주는 돈","r":[]},"위부":{"d":"추정전손 때 보험목적물에 관한 권리를 보험자에게 넘기는 것","r":["추정전손"]},"추정전손":{"d":"실제로 전손은 아니지만 전손이 불가피해 보이는 손해","r":["위부"]},"손해방지비용":{"d":"손해를 막거나 줄이려고 피보험자가 쓴 합리적 비용","r":[]},"이로":{"d":"정당한 이유 없이 계약된 항로를 벗어나는 것","r":[]},"피보험이익":{"d":"보험목적물에 대해 피보험자가 가지는 경제적 이해관계","r":[]},"쌍방과실충돌조항":{"d":"양 선박의 과실 충돌로 화주가 부담하는 책임을 보상하는 조항","r":[]},"본질적 위반":{"d":"상대방이 계약에서 기대할 것을 실질적으로 잃게 하는 위반","r":[]},"Incoterms":{"d":"국제상업회의소가 제정한 무역조건 해석 규칙으로, 매도인·매수인의 의무, 비용, 위험 이전을 정한다.","r":[]},"CISG":{"d":"국제물품매매계약에 관한 유엔협약(1980)으로, 영업소가 서로 다른 체약국에 있는 당사자 사이의 물품매매에 적용된다.","r":[]},"뉴욕협약":{"d":"외국중재판정의 승인 및 집행에 관한 협약(1958)으로, 체약국 법원이 외국 중재판정을 승인·집행하도록 한 협약이다.","r":[]},"declaration":{"d":"협약 체약국이 특정 조항의 적용을 배제하거나 유보하는 취지로 하는 선언이다.","r":[]},"avoidance":{"d":"계약해제로, 일방 당사자의 계약 위반 등을 이유로 계약상 의무를 소멸시키는 행위이다.","r":[]},"suspend":{"d":"상대방이 의무의 실질 부분을 이행하지 않을 것이 분명할 때 자기 이행을 중지하는 것이다.","r":[]},"conformity":{"d":"물품이 계약에서 요구하는 수량, 품질, 포장에 적합한 정도로, 매도인의 적합성 의무에 쓰인다.","r":[]},"risk":{"d":"물품의 멸실이나 훼손에 따른 위험으로, 위험이 매수인에게 이전되면 대금 지급 의무가 남는다.","r":[]},"in transit":{"d":"운송 중인 물품으로, 운송 중 매매에서는 계약 체결 시부터 위험이 이전하는 것으로 볼 수 있다.","r":[]},"carrier":{"d":"운송인으로, 물품 운송 계약을 체결하고 운송을 인수하는 자이다.","r":[]},"MT조약":{"d":"국제물품복합운송에 관한 유엔협약(1980)으로, 복합운송인의 책임 등을 규정한다.","r":[]},"Hamburg Rules":{"d":"해상화물운송에 관한 유엔협약(1978)으로, 운송인 책임을 헤이그규칙보다 강화한 협약이다.","r":[]},"Hague Rules":{"d":"선하증권에 관한 법규의 통일을 위한 국제협약(1924)으로, 해상운송인의 최소 의무와 면책을 정한다.","r":[]},"actual carrier":{"d":"실제운송인으로, 운송인으로부터 운송의 전부나 일부를 위탁받아 이행하는 자이다.","r":[]},"Bill of Lading":{"d":"선하증권으로, 운송인이 화물을 수령·선적했음을 증명하고 화물 인도청구권을 표창하는 유가증권이다.","r":[]},"Sea Waybill":{"d":"해상화물운송장으로, 유통성이 없고 지정된 수하인에게 화물을 인도하게 하는 운송서류이다.","r":[]},"GENCON":{"d":"항해용선계약에 널리 쓰이는 표준계약서 양식이다.","r":[]},"lien":{"d":"유치권으로, 운임이나 대금이 지급될 때까지 화물을 점유하며 지급을 확보하는 권리이다.","r":[]},"항공화물운송장":{"d":"항공운송인이 화물을 수령했음을 증명하는 서류로, 유통성이 없는 운송장이다.","r":[]},"EXW":{"d":"공장인도 규칙으로, 매도인이 자기 구내 등에서 물품을 매수인 처분 하에 두면 인도가 끝난다.","r":[]},"FCA":{"d":"운송인인도 규칙으로, 매도인이 지정 장소에서 매수인이 지정한 운송인 등에게 물품을 인도한다.","r":[]},"CPT":{"d":"운송비지급인도 규칙으로, 매도인이 지정 목적지까지 운송비를 부담하나 위험은 운송인 인도 시 이전된다.","r":[]},"CIP":{"d":"운송비·보험료지급인도 규칙으로, 매도인이 운송비와 보험료를 부담하는 규칙이다.","r":[]},"DAP":{"d":"도착지인도 규칙으로, 매도인이 도착 운송수단 위에서 양하 준비된 상태로 물품을 인도한다.","r":[]},"DPU":{"d":"도착지양하인도 규칙으로, 2020 규칙에서 DAT를 대체하여 매도인이 양하까지 책임진다.","r":[]},"DAT":{"d":"터미널인도 규칙으로, Incoterms 2010에서 지정 터미널에 물품을 양하하여 인도하는 규칙이다.","r":[]},"DDP":{"d":"관세지급인도 규칙으로, 매도인이 수입통관과 관세 납부까지 부담하는 규칙이다.","r":[]},"FAS":{"d":"선측인도 규칙으로, 지정 선적항에서 물품이 선박 선측에 놓이면 인도가 완료된다.","r":[]},"FOB":{"d":"본선인도 규칙으로, 물품이 지정 선적항에서 본선에 적재될 때 인도가 완료된다.","r":[]},"CFR":{"d":"운임포함인도 규칙으로, 매도인이 목적항까지 운임을 부담하나 위험은 선적 시 이전된다.","r":[]},"CIF":{"d":"운임·보험료포함인도 규칙으로, CFR에 매도인의 보험계약 체결 의무가 더해진다.","r":[]},"Delivery":{"d":"인도로, 물품에 대한 위험과 비용이 매도인으로부터 매수인에게 이전되는 기준 시점이다.","r":[]},"GUIDANCE NOTE":{"d":"각 Incoterms 규칙 앞의 사용지침으로, 규칙 적용 방법을 안내하지만 규칙 본문은 아니다.","r":[]},"사용지침":{"d":"각 Incoterms 규칙의 해설로, 규칙 사용 시 고려할 사항을 설명하는 부분이다.","r":[]},"SGA":{"d":"영국물품매매법(Sale of Goods Act, 1979)의 약칭이다.","r":[]},"property":{"d":"소유권으로, 영국물품매매법에서 매도인으로부터 매수인에게 이전되는 권리이다.","r":[]},"MIA":{"d":"영국해상보험법(Marine Insurance Act, 1906)의 약칭이다.","r":[]},"total loss":{"d":"전손으로, 보험목적물이 전부 멸실되었거나 보험목적으로서 가치를 상실한 손해이다.","r":[]},"Partial loss":{"d":"분손으로, 보험목적물의 일부만 입은 손해이다.","r":[]},"deviation":{"d":"이로로, 보험증권상 항로 또는 통상적 항로를 벗어나는 것을 말한다.","r":[]},"delay":{"d":"지연으로, 항해 중 합리적 시간 안에 이행되지 않는 상태이다.","r":[]},"ICC(A)":{"d":"협회적하약관 A조건으로, 전위험담보 조건이다.","r":[]},"ICC(B)":{"d":"협회적하약관 B조건으로, 열거된 위험만 담보하는 조건이다.","r":[]},"ICC(C)":{"d":"협회적하약관 C조건으로, 담보 위험이 가장 좁은 조건이다.","r":[]},"Exclusions":{"d":"면책조항으로, 보험자가 담보하지 않는 손해 원인을 규정한 조항이다.","r":[]},"Both to Blame":{"d":"쌍방과실충돌조항으로, 충돌에서 운송인이 지는 책임액을 화주가 보험자의 보상 범위에서 반환하도록 한 조항이다.","r":[]},"Transit Clause":{"d":"운송약관으로, 보험 개시와 종료 시점을 정한 조항이다.","r":[]},"valued policy":{"d":"보험가액을 미리 약정해 둔 기평가보험증권이다.","r":[]},"Arbitration":{"d":"중재로, 당사자 합의로 중재인에게 분쟁 판단을 맡기고 그 판정에 따르는 분쟁해결 방식이다.","r":[]},"Severability":{"d":"분리가능조항으로, 일부 조항이 무효라도 나머지 조항은 효력을 유지하게 하는 조항이다.","r":[]},"Waiver":{"d":"권리포기조항으로, 권리를 행사하지 않아도 이후 행사할 권리를 잃지 않게 하는 조항이다.","r":[]},"Warranty":{"d":"보증으로, 계약상 품질·성능 등에 관한 약속이며 위반하면 손해배상 책임이 생긴다.","r":[]},"offer":{"d":"청약으로, 계약 체결 의사가 분명하고 승낙만 있으면 계약이 성립하는 의사표시이다.","r":[]},"acceptance":{"d":"승낙으로, 청약에 동의한다는 상대방의 의사표시이다.","r":[]},"Plant":{"d":"플랜트로, 대규모 생산 설비를 설계, 조달, 건설하여 인도하는 사업이다.","r":[]},"UCP 600":{"d":"화환신용장통일규칙 2007년 개정본으로, 신용장 거래의 당사자 권리·의무와 서류심사 기준을 정한다.","r":[]},"eUCP":{"d":"전자적 제시를 위한 UCP 추록으로, 전자기록을 신용장 서류로 제시할 때 적용하는 규칙이다.","r":[]},"URR 725":{"d":"은행 간 화환신용장 대금상환에 관한 통일규칙으로, 상환은행의 상환 절차를 정한다.","r":[]},"URC 522":{"d":"추심에 관한 통일규칙으로, 은행이 서류를 대금 지급이나 인수 조건으로 인도하는 추심 업무를 정한다.","r":[]},"제시":{"d":"신용장에 따른 서류를 개설은행이나 지정은행에 인도하는 행위이다.","r":[]},"서류심사":{"d":"은행이 제시된 서류가 문면상 신용장 조건과 일치하는지 확인하는 절차이다.","r":[]},"거절통지":{"d":"은행이 서류가 불일치하다고 판단해 거절 사유를 통지하는 것이다.","r":[]},"조건변경":{"d":"신용장 조건을 바꾸는 것으로, 개설은행, 확인은행, 수익자의 동의가 필요하다.","r":[]},"양도가능신용장":{"d":"제1수익자의 요청으로 제2수익자가 이용할 수 있게 하는 신용장이다.","r":[]},"운송서류":{"d":"운송인이 운송을 증명하는 서류로, 선하증권, 항공운송서류 등이 있다.","r":[]},"용선계약 선하증권":{"d":"용선계약에 따르는 선하증권으로, 용선계약 조건이 적용됨을 나타낸다.","r":[]},"보험서류":{"d":"보험증권, 보험증명서, 확정보험증서 등 보험이 부보되었음을 증명하는 서류이다.","r":[]},"담보범위":{"d":"보험서류에서 부보되어야 하는 위험과 금액의 범위이다.","r":[]},"원본서류":{"d":"신용장 서류 중 발행자가 원본으로 표시하거나 서명한 서류이다.","r":[]},"불가항력":{"d":"천재지변, 전쟁 등 은행의 통제 밖의 사건으로 은행이 업무를 중단한 경우 면책되는 사유이다.","r":[]},"유효기일":{"d":"신용장에 따라 서류를 제시해야 하는 마지막 날이다.","r":[]},"MT 700":{"d":"SWIFT 신용장 개설용 전문 양식이다.","r":[]},"추심":{"d":"은행이 서류를 받아 지급이나 인수를 받고 서류를 인도하는 업무로, 신용장보다 은행의 지급 확약이 없다.","r":[]},"선하증권":{"d":"운송인이 화물을 수령·선적했음을 증명하고 화물 인도청구권을 나타내는 유가증권이다.","r":[]},"상업송장":{"d":"매도인이 매수인 앞으로 작성하는 물품 명세와 대금 청구서이다.","r":[]},"포장명세서":{"d":"포장 단위별 내용물, 중량, 부피 등을 적은 서류이다.","r":[]},"보험증권":{"d":"보험계약 체결을 증명하는 서류로, 보험목적물과 담보 위험, 보험금액이 적힌다.","r":[]},"담보위험":{"d":"보험자가 보상하기로 한 위험으로, ICC(A)는 면책위험 외 모든 위험을 담보한다.","r":[]},"WTO":{"d":"세계무역기구로, 무역 규범을 정하고 회원국 간 무역 분쟁을 해결한다.","r":[]},"Act of God":{"d":"인간의 힘으로 막을 수 없는 자연재해로, 불가항력의 한 유형이다.","r":[]},"guarantee":{"d":"보증으로, 상품 품질이나 채무 이행을 약속하는 계약이다.","r":[]}},"notes":{"1~10일, 11~20일, 21일~말일":"상순은 1일부터 10일, 중순은 11일부터 20일, 하순은 21일부터 말일까지입니다.","2010의 DAT는 2020에서 DPU(Delivered at Place Unloaded)로 바뀌었다":"개정 전 DAT가 DPU로 이름이 바뀌어 양하 장소가 도착 터미널로 한정되지 않고 어디든 가능해졌습니다.","2020에서 (A) 담보 요구":"CIP는 보험 담보 수준이 더 높아 (A) 조건을 요구합니다.","2020에서 협회적하약관 (C) 담보 요구":"CIF 보험은 최소담보인 (C) 조건을 갖추라고 요구합니다.","A1 일반의무, A2 인도, A3 위험 이전, A4 운송, A5 보험, A6 인도·운송서류, A7 수출입 통관, A8 점검·포장·화인, A9 비용 분담, A10 통지":"개정판은 열 개 조항이 일반의무부터 통지까지 정해진 순서로 이어집니다.","A3 운송·보험, A4 인도, A5 위험, A9 점검·포장·화인 순":"이전 판은 운송과 보험을 A3에 두고 인도 A4, 위험 A5, 점검과 포장, 화인은 A9에 둔 순서였습니다.","Certificate of Origin: 물품이 협정이 정한 원산지 요건을 충족함을 증명":"원산지증명서는 물품이 협정에서 정한 원산지 요건을 충족한다는 사실을 증명하는 서류입니다.","Consular Invoice: 수입국 영사가 확인한 송장":"영사송장은 수입국 영사가 확인하여 수출입 거래를 증명하는 송장입니다.","Delivery Order: 보관자에게 특정인에게 화물을 내주라고 지시하는 서류":"화물인도지시서는 화물을 가진 자에게 특정인에게 화물을 내주라고 지시하는 서류입니다.","Dock Receipt: 부두에서 화물을 받았다는 서류":"부두수취증은 화물이 부두에 도착해 접수되었음을 증명하는 서류입니다.","EXW·FCA·CPT·CIP·DAP·DPU·DDP":"이 일곱 규칙은 운송 방식이 정해져 있지 않아 컨테이너나 항공 등 어떤 운송에도 쓸 수 있습니다.","FAS·FOB·CFR·CIF":"이 네 규칙은 본선에 물건을 싣고 내리는 해상이나 내수로 운송에만 쓸 수 있습니다.","FCA·DAP·DPU·DDP에서 자기 운송수단으로 운송할 수 있음":"FCA, DAP, DPU, DDP에서는 당사자가 별도 운송인 없이 자기 운송수단으로 운송해도 됩니다.","Incoterms의 운송서류·보험 규정은 운송인·보험자·은행을 구속하지 않는다(do not bind)":"Incoterms 운송과 보험 규정은 당사자 사이의 약속이라 운송인과 보험자, 은행을 법적으로 묶지 못합니다.","SOLAS 협약에 따라 송하인은 컨테이너 총중량을 검증해 운송인에게 제출한다":"컨테이너 총중량은 송하인이 검증해서 운송인에게 내야 한다는 것이 SOLAS 협약의 요구입니다.","about·approximately가 붙은 금액·수량·단가":"about이나 approximately가 앞에 붙으면 정해진 금액과 수량, 단가에 어느 정도 과부족이 허용된다는 뜻입니다.","anti-dumping duties: 덤핑에 매김":"반덤핑관세는 수출국이 정상 가격보다 싸게 판 덤핑 수입에 대해 매기는 관세입니다.","counter offer: 상대 청약에 조건을 바꿔 다시 제안하는 서신":"반대청약은 상대의 청약에 조건을 바꿔 다시 내놓는 제안이라 상대 청약을 거절한 효과가 있습니다.","countervailing duties: 수출국 보조금에 매김":"상계관세는 수출국 정부의 보조금을 받은 수입품에 그 보조금을 상쇄하려고 매기는 관세입니다.","credit inquiry: 거래처의 신용 상태를 묻는 서신":"신용조회 서신은 거래 상대의 신용 상태가 어떤지 은행이나 기관에 묻는 편지입니다.","first class, well known, qualified, independent, official, competent, local 같은 말로 발행인을 적으면 수익자를 뺀 누구든 그 서류를 발행할 수 있다":"발행인을 first class 같은 모호한 말로 적으면 수익자를 뺀 누구든 그 서류를 발행할 수 있습니다.","quota: 일정 기간 수입 물량을 제한하는 조치":"쿼터는 일정 기간 동안 수입할 수 있는 물량의 상한을 두는 조치입니다.","red clause credit":"red clause credit은 선적 전에 수익자가 대금 일부를 미리 받을 수 있는 선대신용장입니다.","revolving credit":"revolving credit은 일정 조건에 따라 금액이 되살아나 반복해 쓸 수 있는 회전신용장입니다.","safeguard measure:":"세이프가드는 수입이 늘어 국내 산업이 입는 피해를 막으려고 수입을 일시 제한하는 무역구제 조치입니다.","가격 인하를 조건으로 주문하겠다는 서신이 해당":"가격을 내려 주면 주문하겠다는 서신은 조건을 붙인 것이라 반대청약에 해당합니다.","갑판 유실(washing overboard)":"(B)는 (C)보다 담보위험이 넓어 갑판 유실도 보상합니다.","같은 종류의 물품이 통상 쓰이는 목적과 매도인이 알았던 특정 목적에 맞아야 한다":"물품은 보통 쓰는 용도에 맞아야 하고 매도인이 알았던 특정 용도에도 맞아야 합니다.","개설은행·확인은행·수익자의 동의 없이는 효력이 없다":"조건변경은 개설은행과 확인은행, 수익자가 모두 동의하지 않으면 효력이 없습니다.","개설의뢰인과 개설은행·수익자 사이의 관계에서 생긴 항변으로 지급을 거절할 수 없다":"개설의뢰인과 은행 사이나 은행과 수익자 사이 관계에서 생긴 주장을 이유로 지급을 미룰 수 없습니다.","개설의뢰인 앞으로 발행된 환어음으로 이용하게 해서는 안 된다":"환어음을 개설의뢰인 앞으로 발행하는 방식으로는 신용장을 이용하게 해서는 안 됩니다.","개인·가족·가정용 물품 매매, 경매, 강제집행 등 법률상 권한에 의한 매매, 주식·유가증권·유통증권·화폐, 선박·항공기, 전기의 매매에는 적용하지 않는다":"개인용 물품 매매와 경매, 강제집행, 주식과 유가증권, 화폐, 선박과 항공기, 전기의 매매에는 적용하지 않습니다.","계약과 그 이행에 가장 밀접한 곳이 영업소":"영업소가 여럿이면 계약과 그 이행에 가장 밀접한 곳을 영업소로 봅니다.","계약 때 매수인이 부적합을 알았거나 모를 수 없었으면 매도인은 책임이 없다":"계약할 때 하자를 알았거나 모를 수 없었던 매수인에게는 매도인이 책임지지 않습니다.","계약은 서면으로 체결하거나 증명할 필요가 없고, 서면(writing)에는 전보와 텔렉스가 포함":"계약은 서면으로 체결하거나 증명할 필요가 없고 서면에는 전보와 텔렉스도 포함됩니다.","계약 체결 시 매수인에게 넘어간다":"운송 중 매매는 위험이 계약을 체결할 때 매수인에게 넘어갑니다.","공급자 의무의 대부분이 노무·서비스인 계약과, 물품으로 인한 사람의 사망·상해에 대한 매도인 책임도 제외된다":"공급자 의무가 주로 노무인 계약과 물품으로 인한 사람의 사망이나 상해에 대한 매도인 책임도 협약 밖입니다.","구제수단을 쓸 때 법원·중재판정부는 매수인에게 유예기간을 줄 수 없다":"매수인이 구제수단을 쓸 때 법원이나 중재판정부가 매도인에게 유예기간을 줄 수 없습니다.","국제사법 규칙이 체약국 법을 지정할 때도 적용":"국제사법 규칙에 따라 체약국 법을 적용하게 되는 경우에도 협약이 적용됩니다.","그래서 F·C 규칙 7개를 선적(shipment) 매매라고 한다":"위험이 선적 때 이전되므로 F와 C 규칙 일곱 개를 선적매매라 부릅니다.","그 밖에 추심에 관여하는 은행":"추심에 관여하는 은행 중 추심의뢰은행이 아닌 그 밖의 은행은 모두 추심은행입니다.","그 통화를 즉시 처분할 수 있을 때만 지급인에게 인도":"지급국 통화로 지급하는 서류는 그 통화를 바로 처분할 수 있을 때만 지급인에게 인도합니다.","근거가 된 매매계약과 별개의 거래(제4조)":"신용장은 그 바탕이 된 매매계약과 별개의 거래라는 독립성이 있습니다.","금액·단가·유효기일·선적기간은 줄이거나 앞당겨 양도할 수 있고 보험 부보비율은 높일 수 있다":"양도할 때 금액과 단가, 유효기일, 선적기간은 줄이거나 앞당길 수 있고 보험 부보비율은 높일 수 있습니다.","금융서류 없이 상업서류만 추심":"금융서류 없이 선적서류 같은 상업서류만 추심하는 것도 화환추심에 해당합니다.","남의 특허 등을 허락 없이 실시하는 것":"infringement는 남의 특허나 상표 등을 허락 없이 실시해 권리를 침해하는 일입니다.","넣으면서 지급인도를 지시해서는 안 된다":"미래 일자 환어음이 든 추심에는 지급인도를 지시하지 않아야 합니다.","다른 장소를 정하지 않았으면 매수인은 매도인의 영업소에서, 또는 물품·서류 인도와 상환이면 그 인도 장소에서 지급":"지급 장소를 정하지 않았다면 매도인의 영업소에서, 인도와 맞바꾸는 경우는 그 인도 장소에서 냅니다.","당사자 국적과 민사·상사 성격":"협약을 적용할 때는 당사자의 국적이나 계약의 민사 또는 상사 성격을 고려하지 않습니다.","대금·지급·품질·수량·인도 장소와 시기·책임 범위·분쟁 해결을 바꾼 회신":"대금이나 품질 같은 중요한 조건을 바꾼 회신은 승낙이 아니라 새 청약인 반대청약입니다.","대리인이 아니라 본인(principal)으로서 계약 전체에 책임":"복합운송인은 대리인이 아니라 본인으로서 계약 전체에 대해 책임을 집니다.","대체물 인도(본질적 위반일 때만)":"대체물 인도를 청구하는 구제수단은 부적합이 본질적 위반일 때에만 쓸 수 있습니다.","도착 운송수단 위에서 양하 준비된 채로":"DAP는 도착한 운송수단 위에서 내릴 준비를 마친 채 두는 것이 인도입니다.","동의 표시가 청약자에게 도달한 때 효력이 생긴다(도달주의)":"승낙은 동의 표시가 청약자에게 닿은 때에야 효력이 생기는 도달주의를 따릅니다.","매도인의 요구나 다른 절차 없이 기일에 지급해야 한다":"매수인은 매도인의 요구나 다른 절차 없이도 기일이 되면 대금을 지급해야 합니다.","매도인이 물품이나 처분권 서류를 매수인 처분하에 두는 때":"지급시기는 매도인이 물품이나 처분권 서류를 매수인의 처분 아래 두는 때입니다.","매수인은 실행 가능한 짧은 기간 안에 검사하고, 인도 후 2년이 지나면 부적합을 주장할 수 없다":"매수인은 가능한 한 빨리 검사해야 하며 인도 후 2년이 지나면 부적합을 이유로 다툴 수 없습니다.","매수인의 대금 지급 의무를 없애지 않지만, 그 손실이 매도인의 작위나 부작위 때문이면 예외":"위험이 넘어간 뒤 멸실되어도 매수인의 지급 의무는 그대로지만 매도인의 작위나 부작위 탓이면 예외입니다.","매수인이 매도인 구내에서 수거(collection)할 때":"EXW는 매도인 구내에서 매수인이 직접 물건을 가져가는 때가 인도입니다.","매수인이 지정한 운송인에게 넘길 때":"FCA는 매수인이 지정한 운송인에게 물건을 넘기는 때가 인도입니다.","매수인 쪽 B9는 물품 검사(Inspection of goods)":"매수인 쪽 조항 B9에는 물품 검사가 들어 있습니다.","면책 사유를 뺀 모든 위험을 담보하는 포괄담보":"ICC(A)는 면책 사유를 뺀 모든 위험을 담보하는 포괄담보 조건입니다.","물품·수량·대금을 정하거나 정할 방법을 두면 확정적":"물품과 수량, 대금을 정했거나 정하는 방법이 있으면 확정적인 청약으로 봅니다.","받은 서류가 지시서 목록과 같아 보이는지만 확인한다":"은행은 서류가 지시서 목록과 겉으로 같아 보이는지만 확인하면 의무를 다한 것입니다.","밝히지 않으면 지급과 상환으로만 인도한다":"인도 조건을 밝히지 않으면 서류는 지급과 상환으로만 인도합니다.","보험금을 낸 보험자가 피보험자의 제3자에 대한 권리를 넘겨받는 것":"보험금을 지급한 보험자가 피보험자를 대신해 제3자에게 권리를 행사하게 되는 제도가 대위입니다.","보험금을 지급한 보험자가 제3자에 대한 피보험자의 권리를 취득하는 것":"대위는 보험금을 지급한 보험자가 제3자에 대한 피보험자의 권리를 넘겨받는 제도입니다.","보험목적물의 협정가액을 적은 증권":"기평가보험증권은 사고 전에 보험목적물의 가액을 미리 협정해 적은 증권입니다.","보험자에게서 회수할 수 있다":"공동해손 분담금은 피보험자가 낸 뒤 보험자에게서 회수할 수 있습니다.","본선에 적재(on board)될 때":"FOB와 CFR, CIF는 물건이 본선에 실리는 순간이 인도입니다.","본선적재 표기 선하증권을 발행하게 할 수 있게 함":"매수인이 요청하면 선적 후 본선적재 표기가 있는 선하증권을 발행하게 하는 선택이 FCA에 생겼습니다.","부도 때 대신 처리할 대리인이며 권한을 지시서에 분명히 적는다":"예비지급인은 지급인이 부도를 낼 때 대신 처리하는 대리인이며 권한은 지시서에 명확히 적습니다.","부분 이익도 보험에 붙일 수 있고, 선장과 선원은 임금에, 보험자는 자기 위험에 피보험이익이 있어 재보험을 들 수 있다":"보험자는 인수한 위험에, 선장과 선원은 임금에 각각 이익이 있고 부분 이익도 보험에 붙일 수 있습니다.","불특정 다수에게 한 제안은 반대 표시가 없으면 청약의 유인(invitation to make offers)":"불특정 다수를 향한 제안은 반대 표시가 없으면 청약이 아니라 청약을 유도하는 행위입니다.","사용자를 위한 설명문(Explanatory Notes for Users)을 새로 둠":"이용자가 규칙을 이해하도록 돕는 설명문을 새로 붙였다는 개정 내용입니다.","산 동물의 고유 위험과 인명·재산 구조 조치로 생긴 손해":"산 동물의 고유 위험과 인명이나 재산을 구하려는 조치로 생긴 손해는 운송인이 면책됩니다.","상대방이 의무의 실질적 부분을 이행하지 않을 것이 명백해지면 이행을 정지할 수 있다":"상대가 의무의 중요한 부분을 이행하지 않을 것이 분명하면 자기 이행을 멈출 수 있습니다.","상업서류가 붙은 금융서류를 추심":"화환추심은 금융서류에 상업서류가 붙은 상태로 추심하는 것입니다.","서류를 인수인도(D/A)할지 지급인도(D/P)할지 지시서에 밝혀야 한다":"환어음이 든 추심에서는 서류를 인수와 지급 중 어느 조건으로 인도할지 지시서에 밝혀야 합니다.","서류 심사는 완전성 통지를 받은 날의 다음 은행영업일부터 시작":"전자서류 제시 규칙에서는 완전성 통지를 받은 날의 다음 은행영업일부터 서류 심사가 시작됩니다.","서면 요건 유보를 선언한 체약국에 영업소가 있는 당사자에게는 제11조가 적용되지 않는다":"서면 요건 유보 선언국에 영업소를 둔 당사자에게는 서면 불요 조항인 제11조가 통하지 않습니다.","선박명 등 세부를 뒤에 신고로 정하는 증권":"포괄예정보험증권은 선박명 같은 세부 내용을 나중에 신고로 확정하는 증권입니다.","선장·선원의 항해·선박관리 과실(항해과실)과 화재로 생긴 손해":"선장과 선원의 항해과실이나 화재로 생긴 손해는 헤이그 규칙에서 운송인이 면책됩니다.","선적·양하 중 추락한 포장당 전손":"(B)는 선적이나 양하 중 추락한 포장당 전손도 보상합니다.","선적하지 못한 부분에 내는 운임":"부적운임은 화물을 싣지 못해 빈 선복이 생긴 부분에 대해 내는 운임입니다.","선주가 운임·체선료 등 용선계약상 금액에 대해 화물에 가짐":"유치권은 선주가 운임이나 체선료를 받을 때까지 화물을 붙잡아 둘 수 있는 권리입니다.","선하증권 같은 권리증권으로 증명되지 않는 운송계약에 적용":"해상화물운송장 규칙은 선하증권 같은 권리증권으로 증명되지 않는 운송계약에 적용됩니다.","손해방지비용으로 보상받지 못한다":"공동해손 분담금과 구조비는 손해방지비용 조항으로는 보상받지 못하고 별도 조항으로 다룹니다.","송하인만 운송인에게 지시할 수 있고, 물품 수령 전에는 처분권을 수하인에게 넘길 수 있다":"운송인에게 지시할 수 있는 자는 송하인뿐이며 물품 수령 전에는 이 권리를 수하인에게 넘길 수 있습니다.","송하인이 성질·가액을 고의로 허위 기재하면 운송인은 책임지지 않는다":"송하인이 일부러 물품의 성질이나 가액을 거짓으로 적으면 운송인에게 책임을 물을 수 없습니다.","송하인이 원본 3통으로 작성하고 다른 기록 보존 수단으로 대체할 수 있다(may be substituted)":"항공화물운송장은 송하인이 원본 3통으로 작성하되 다른 기록 수단으로 대체할 수도 있습니다.","수락을 통지할 때까지는 원래 조건이 유효하고, 일부만 수락하면 거절로 본다":"수익자가 수락을 알리기 전에는 원래 조건이 그대로이며 일부만 수락하면 거절한 것으로 봅니다.","수량을 포장단위나 개수로 적지 않았고 인출액이 신용장 금액을 넘지 않으면 허용":"수량을 개수나 포장단위로 쓰지 않았고 인출액이 신용장 금액 이내이면 수량 과부족을 허용합니다.","수입 급증으로 국내 산업이 심각한 피해를 입거나 입을 우려가 있을 때":"수입이 갑자기 늘어 국내 산업이 큰 피해를 입었거나 입을 우려가 있을 때 쓰는 조치입니다.","수출자가 선적요청서(S/R)로 선복을 신청 → 선사가 선적지시서(S/O)를 냄 → 선적 후 본선수취증(M/R)을 받음 → 선하증권과 교환":"선적요청서로 선복을 신청해 선적지시서를 받고, 선적 후 본선수취증을 선하증권과 교환하는 순서입니다.","승인·집행국이 아닌 나라에서 내려진 중재판정에 적용, 상설 중재기관의 판정도 포함":"승인과 집행을 하는 나라가 아닌 곳에서 내려진 중재판정이 대상이며 상설 중재기관의 판정도 포함합니다.","신용장 거래에서 개설은행이나 지정은행":"지급인은 환어음의 대금을 지급해야 하는 사람으로 신용장에서는 개설은행이나 지정은행입니다.","양하까지 마친 뒤 매수인 처분하에 둘 때":"DPU는 도착 장소에서 매도인이 직접 내려 주는 일까지 마쳐야 인도가 이루어집니다.","어음을 상환청구권 없이 사들이는 것이어서 수입자가 지급하지 않아도 수출자에게 되돌아오지 않는다":"forfaiting은 어음을 상환청구권 없이 사들이므로 수입자가 지급하지 않아도 수출자에게 되돌아오지 않습니다.","여러 통이면 모두 제시, franchise·excess(공제) 적용 표시는 허용":"보험서류 원본이 여러 통이면 모두 제시하고 공제 적용 표시는 허용됩니다.","영업소가 서로 다른 체약국에 있는 당사자 사이의 물품매매":"서로 다른 체약국에 영업소를 둔 당사자가 물품을 사고팔 때 협약이 적용됩니다.","완전합의(Entire agreement), 분리가능성(Severability), 권리불포기(Non-Waiver), 사정변경(Hardship), 준거법(Governing law), 지연위약금(liquidated damages)이 자주 나온다":"계약서에는 완전합의와 분리가능성, 권리불포기, 사정변경, 준거법, 지연위약금 조항이 자주 들어갑니다.","외상매출채권을 팩터가 사들여 대금 회수와 신용위험을 맡는 방식":"팩토링은 팩터가 외상매출채권을 사들여 대금 회수와 신용위험을 맡는 방식입니다.","운송계약의 쌍방과실충돌조항(Both to Blame Collision Clause)에 따라 피보험자가 지는 책임도 ICC가 보상한다":"쌍방과실충돌조항에 따라 피보험자가 상대 선박에 지는 책임도 ICC가 보상합니다.","운송 의무와 비용에 보안 요건을 넣었고, 비용을 A9/B9 한 곳에 모아 적음":"운송 의무와 비용에 보안 요건이 들어가고, 비용 조항을 A9와 B9 한 곳으로 모았습니다.","운송이 포함되면 인도는 최초 운송인에게 물품을 넘기는 것":"운송이 포함된 계약에서는 최초 운송인에게 물품을 넘기는 것이 인도입니다.","운송인에게서 운송을 위탁받은 자이고, 둘 사이의 구상권은 영향받지 않는다":"실제운송인은 운송인에게서 운송을 위탁받은 자이고 운송인과의 구상권은 영향받지 않습니다.","운송인 유보가 없으면 수량·상태 기재는 운송인과 송하인 사이에서는 추정적 증거, 운송인과 선의의 수하인 사이에서는 확정적 증거":"운송인이 유보하지 않으면 기재는 송하인과의 관계에서는 추정적, 선의의 수하인과의 관계에서는 확정적 증거입니다.","운송인은 선적 때부터 양륙 때까지 책임":"헤이그 규칙에서 운송인은 선적할 때부터 양륙할 때까지만 책임을 집니다.","운송인은 선적항·운송 중·양륙항에서 물품을 관리하는 기간 동안 책임지고 항해과실 면책은 없다":"함부르크 규칙은 운송인이 물품을 관리하는 기간 전체에 책임을 지고 항해과실 면책이 없습니다.","운송인 책임을 협약보다 줄이는 약관은 무효이지만 권리 포기나 책임 가중은 할 수 있다":"운송인 책임을 협약보다 줄이는 약관은 무효이지만 권리를 포기하거나 책임을 늘리는 약관은 가능합니다.","원본 선하증권이 도착하기 전에 은행 보증으로 화물을 먼저 받는 서류":"화물선취보증서는 선하증권 원본이 늦게 도착할 때 은행이 보증을 서고 화물을 먼저 받게 해 주는 서류입니다.","위부의 포기나 수락으로 보지 않는다":"손해를 줄이려고 취한 구조나 보호 조치는 위부를 포기하거나 수락한 것으로 보지 않습니다.","위탁수하물 7일, 화물 14일, 지연은 21일 안에 하고, 협약의 일(days)은 역일(calendar days)":"손상 이의는 위탁수하물 7일, 화물 14일, 지연 21일 안에 하며 일수는 달력상의 날입니다.","위험은 선적지에서 이미 넘어간다":"C 규칙은 물건을 선적지에서 인도하는 순간 위험이 매수인에게 넘어가고, 목적지는 운임 부담의 한계일 뿐입니다.","위험은 최초 운송인에게 인도된 때":"운송이 포함된 매매에서 위험은 최초 운송인에게 물품이 인도된 때 넘어갑니다.","은행은 불가항력으로 영업이 중단된 동안 유효기일이 지난 신용장은 영업 재개 뒤에도 지급·매입하지 않는다":"불가항력으로 문을 닫은 사이에 유효기일이 지난 신용장은 영업을 재개해도 은행이 대금을 주지 않습니다.","은행은 서류를 다루며 물품·서비스·이행을 다루지 않는다(제5조)":"은행은 서류만 보고 판단하므로 물품이나 서비스, 계약 이행 여부는 심사 대상이 아닙니다.","은행은 추심이나 추심지시서를 취급할 의무가 없고, 취급하지 않기로 하면 지체 없이 알린다":"은행은 추심 의뢰를 반드시 받아야 하는 것이 아니라서 취급하지 않기로 하면 지체 없이 알립니다.","의뢰인에게 추심을 받은 은행":"추심을 의뢰한 사람에게서 추심을 받아 맡는 은행을 추심의뢰은행이라 합니다.","이익의 상실(loss of profit)을 포함하되 계약 때 예견할 수 있었던 손실을 넘지 못한다":"손해배상은 이익의 상실을 포함하되 계약 체결 때 예견할 수 있던 손실을 넘지 못합니다.","이행기 전에 본질적 위반이 명백하면 해제할 수 있다":"이행기가 오기 전이라도 본질적 위반이 분명해지면 계약을 해제할 수 있습니다.","인도기일 뒤에도 부당한 지연 없이 자기 비용으로 불이행을 치유할 수 있다":"매도인은 인도기일이 지난 뒤에도 자기 비용으로 부당한 지연 없이 고쳐서 이행할 수 있습니다.","일람지급(sight payment), 연지급(deferred payment), 인수(acceptance), 매입(negotiation) 중 어느 방법으로 이용하는지 밝혀야 한다":"신용장은 일람지급, 연지급, 인수, 매입 가운데 어느 방식으로 이용하는지 밝혀야 합니다.","자기 은행에서 매입으로 이용되는 신용장이면 상환청구권 없이(without recourse) 매입한다":"자기 은행에서 매입 방식으로 이용되는 신용장은 상환청구권 없이 매입합니다.","적어도 두 가지 다른 운송수단으로 한 나라의 인수지에서 다른 나라의 지정 인도지까지 운송하는 것이다":"국제복합운송은 최소 두 가지 다른 운송수단으로 한 나라의 인수지에서 다른 나라의 인도지까지 운송합니다.","전보 발신 제출 시나 서신 일자(없으면 봉투 일자)부터":"전보나 편지로 정한 승낙기간은 전보를 낸 때나 편지에 적힌 날짜부터 세기 시작합니다.","전신송금(T/T), 우편송금(M/T), 송금수표(D/D) 방식이 있고 주문과 함께 내는 CWO, 물품과 상환하는 COD가 있다":"송금은 전신, 우편, 수표 방식이 있고 주문과 함께 내는 CWO와 물품과 맞바꾸는 COD가 있습니다.","정당한 이유 없이 이로(deviation) → 보험자는 이로한 때부터 책임을 면하고, 손해 전에 원 항로로 돌아와도 같다 → 담보 이행, 선박·화물 안전, 인명 구조, 선장·선주가 통제할 수 없는 사정을 위한 이로와 지연은 허용된다":"정당한 이유 없는 이로는 보험자가 이로한 때부터 책임을 면하고, 허용되는 사유가 있으면 이로가 정당화됩니다.","제시은행은 부도 이유를 확인해 추심의뢰은행에 통지하고, 이후 처리 지시는 추심의뢰은행이 한다":"제시은행이 부도 이유를 확인해 의뢰은행에 알리면 그 뒤 처리는 추심의뢰은행의 지시에 따릅니다.","제품이 일정 기간 안에 불량이면 교환·수리·환불하겠다는 생산자의 약속":"guarantee는 제품이 일정 기간 안에 불량이면 교환이나 수리, 환불을 해 주겠다는 생산자의 약속입니다.","조건변경을 발행한 때부터 취소불능으로 구속":"개설은행은 조건변경을 발행한 때부터 취소할 수 없게 그 내용에 묶입니다.","중간항에서 인도하기로 새로 합의했을 때의 운임":"비율운임은 중간항에서 인도하기로 새로 합의했을 때 운항한 거리에 비례해 정해지는 운임입니다.","중재로 해결할 수 없는 분쟁이거나 그 나라 공서(public policy)에 반하면 집행국 기관이 직권으로 거부할 수 있다":"중재로 풀 수 없는 분쟁이거나 그 나라의 공서에 어긋나면 집행국 기관이 직권으로 집행을 거부할 수 있습니다.","증권에 다른 정함이 없는 한 피보험자는 어느 보험자에게든 청구할 수 있지만 법이 허용하는 보상액을 넘겨 받을 수 없다":"중복보험에서는 어느 보험자에게든 청구할 수 있으나 법이 허용하는 보상액을 넘게 받지는 못합니다.","지급·매입 요청액과 송장 총액 중 큰 금액을 기준으로 한다":"가액을 알 수 없으면 지급이나 매입 요청액과 송장 총액 중 큰 금액을 기준으로 삼습니다.","지급인 부담으로 했는데 지급인이 거절하면 지시서에 따로 정함이 없는 한 제시은행은 수수료 없이 서류를 인도할 수 있다":"수수료를 지급인 부담으로 했는데 지급인이 거절하면 제시은행은 수수료 없이 서류를 인도할 수 있습니다.","지급인에게 제시하는 추심은행":"지급인에게 직접 서류를 제시하는 추심은행이 제시은행입니다.","지급인이 조치할 기간을 적는다":"지시서에는 지급인이 필요한 조치를 취해야 하는 기간을 적습니다.","지시를 받았더라도 마찬가지이다":"물품에 대한 조치를 지시받았더라도 은행에 같은 이유로 그 조치를 할 의무가 생기지 않습니다.","지정은행·확인은행·개설은행은 제시일 다음 날부터 최대 5은행영업일 안에 일치 여부를 정함 → 운송서류 원본은 선적일 후 21일 안에, 유효기일 안에 제시 → 서류상 자료는 같을 필요는 없지만 상충해서는 안 됨 → 거절은 불일치 사항을 모두 적어 한 번에 통지":"은행은 제시 다음 날부터 5은행영업일 안에 일치 여부를 정하며, 불일치는 한 번에 모두 적어 통지합니다.","지정일 전후 5일(양 끝 포함)":"on or about은 지정일 앞뒤 닷새를 양 끝 날짜를 포함해 허용하는 표현입니다.","지정 장소는 매도인이 운송을 마련하고 운임을 부담하는 목적지":"C 규칙에서 지정 장소는 매도인이 운임을 부담해 운송을 마련하는 도착지일 뿐이라 위험 이전 장소와 다릅니다.","지정 장소는 인도 장소, 곧 위험이 이전하는 곳이다":"C 규칙을 뺀 규칙에서는 정해 둔 장소가 인도하는 곳이면서 위험이 매수인에게 넘어가는 곳입니다.","창고에서 운송을 시작할 때 개시되어 통상의 운송 중 계속된다":"담보기간은 창고에서 운송을 시작할 때 개시되어 통상의 운송 중에 이어집니다.","철회(withdrawal) 통지가 청약보다 먼저 또는 동시에 도달하면 취소불능 청약도 거둘 수 있다":"철회 통지가 청약보다 먼저나 동시에 도달하면 취소할 수 없는 청약도 거둘 수 있습니다.","청약은 도달 시 효력이 생긴다":"청약은 상대방에게 도달하는 순간부터 효력이 생깁니다.","청약이 피청약자(offeree)에게 도달한 때부터":"전화나 텔렉스처럼 즉시 통신으로 한 청약은 상대에게 도달한 때부터 기간을 셉니다.","청약자가 지체 없이 이의하지 않으면 승낙이 된다":"조건을 바꿨어도 실질적 변경이 아니면 청약자가 바로 이의하지 않는 한 승낙이 성립합니다.","체약국은 서면 중재합의(agreement in writing)를 승인해야 한다":"체약국은 당사자가 서면으로 한 중재합의를 승인해야 합니다.","최소 CIF·CIP 가액의 110%":"보험서류의 부보금액은 최소한 CIF나 CIP 가액의 110퍼센트가 되어야 합니다.","최종 양하항에서 본선 양하를 마친 뒤 60일이 지나면 목적지 창고에 들어가지 않아도 끝난다":"목적지 창고에 들어가지 못해도 최종 양하항에서 양하를 마치고 60일이 지나면 담보가 끝납니다.","추심지시서에 따라 제시를 받는 자":"추심지시서에 따라 서류를 제시받는 사람이 지급인입니다.","추정전손 때 목적물을 보험자에게 넘기는 것":"위부는 추정전손에서 보험목적물에 관한 권리를 보험자에게 넘기고 보험금을 청구하는 제도입니다.","침묵이나 부작위만으로는 승낙이 되지 않는다":"가만히 있거나 아무 행동도 하지 않는 것만으로는 승낙으로 인정되지 않습니다.","타인의 위법행위에 의한 고의적 손상은 (B)·(C)에서만 면책":"타인이 일부러 손상한 경우는 (A)만 보상하고 나머지 두 조건은 면책한다는 구조입니다.","태풍·낙뢰처럼 사람이 통제할 수 없는 자연현상":"Act of God는 태풍과 낙뢰처럼 사람이 통제할 수 없는 자연현상으로 면책 사유가 됩니다.","통고 접수일부터 1년 후 효력":"협약을 폐기하는 통고는 접수일부터 1년이 지나야 효력이 생깁니다.","통제할 수 없는 장애로 불이행한 당사자는 손해배상 책임을 면하지만 장애를 합리적 기간 안에 통지해야 하고, 상대방의 다른 구제권은 남는다":"통제할 수 없는 장애 때문이면 배상책임을 지지 않지만 장애를 합리적인 기간 안에 알려야 합니다.","특정인에게 한, 충분히 확정적인 제안":"청약은 상대가 특정되어 있고 계약이 성립할 만큼 구체적으로 확정된 제안이어야 합니다.","포장당 666.67 SDR 또는 kg당 2 SDR 중 큰 금액을 한도":"헤이그비스비 규칙은 포장당 666.67 SDR과 kg당 2 SDR 중 큰 금액을 책임한도로 삼습니다.","포장당 920 SDR 또는 kg당 2.75 SDR 중 높은 금액":"복합운송인의 책임한도는 포장당 920 SDR과 kg당 2.75 SDR 중 높은 금액입니다.","피보험자가 모르는 사이 선박이 다른 목적지로 가면 보험은 운송 개시 시부터 그대로 유효하다":"선박이 피보험자 몰래 목적지를 바꿔도 운송이 시작된 때부터 보험은 그대로 효력이 있습니다.","피보험자가 위부(abandonment)를 택하면 보험자에게 위부 통지를 해야 한다":"추정전손에서 피보험자가 위부를 선택하면 보험자에게 위부 통지를 해야 합니다.","피보험자는 손해를 막거나 줄이는 합리적 조치를 할 의무가 있고 그 비용은 보상받는다":"피보험자는 손해를 막거나 줄이는 합리적 조치를 해야 하고 그 비용은 보험자에게서 보상받습니다.","피보험자의 고의적 위법행위, 통상의 누손·자연소모, 포장 불충분, 고유의 하자, 지연, 선주의 지급불능, 핵무기 사용이다":"피보험자의 고의 위법행위, 통상의 누손, 포장 불충분, 고유의 하자, 지연, 핵무기 사용은 일반면책입니다.","한 번만 할 수 있고 수수료는 별도 합의가 없으면 제1수익자가 낸다":"신용장 양도는 한 번만 가능하고 별도 합의가 없으면 수수료는 제1수익자가 부담합니다.","합법화·사증·증명 요건은 그렇게 보이는 서명·스탬프·라벨이 있으면 충족된다":"합법화나 증명 요건은 그에 맞는 서명, 스탬프, 라벨이 서류에 있으면 충족됩니다.","허용 정박기간을 넘긴 데 대해 선주에게 주는 돈":"체선료는 허용된 정박기간을 넘겨 선박을 붙잡아 둔 것에 대해 선주에게 주는 돈입니다.","협약은 국제적 성격, 적용의 통일, 국제거래의 신의성실(good faith)을 고려해 해석":"협약을 해석할 때는 국제적 성격과 통일적 적용, 국제거래의 신의성실을 고려합니다.","화물 고유 결함, 운송인 측이 아닌 자의 불완전 포장, 전쟁, 공권력 행위":"운송인은 화물 고유의 결함과 운송인 아닌 자의 불완전 포장, 전쟁, 공권력 행위로 인한 손해를 면책받습니다.","화환추심의 물품에 대해 보관·보험 등 어떤 조치도 할 의무가 없다":"화환추심 물품은 은행이 보관이나 보험 같은 조치를 할 의무 대상이 아닙니다.","확인을 연장하지 않고 통지만 할 수도 있다":"확인은행은 조건변경에 확인을 연장해도 되고, 연장 없이 통지만 해도 됩니다.","환어음·약속어음을 상환청구권 없이(non-recourse) 할인 매입하는 중장기 금융":"포페이팅은 환어음이나 약속어음을 상환청구권 없이 할인해 매입하는 중장기 금융입니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
